from typing import Optional

# Reuse the existing internal skill if available.
try:
    from version_compare import compare_versions  # type: ignore
except Exception:  # pragma: no cover
    # Fallback: minimal numeric dotted compare.
    import re

    _NUMBER_RE = re.compile(r"\d+")

    def _split_version(v: str) -> tuple[int, ...]:
        parts = _NUMBER_RE.findall(str(v))
        if not parts:
            return (0,)
        return tuple(int(p) for p in parts)

    def compare_versions(a: str, b: str) -> int:
        va = _split_version(a)
        vb = _split_version(b)
        max_len = max(len(va), len(vb))
        for i in range(max_len):
            ai = va[i] if i < len(va) else 0
            bi = vb[i] if i < len(vb) else 0
            if ai < bi:
                return -1
            if ai > bi:
                return 1
        return 0


def newest_compatible(versions: list[str], minimum: str) -> str | None:
    """
    Return the highest version from `versions` that is >= `minimum`,
    using component-wise numeric comparison for dotted release versions.

    Returns None if no version qualifies. The returned string is exactly
    one of the input strings from `versions` (not normalized).
    """
    best: Optional[str] = None
    for v in versions:
        if compare_versions(v, minimum) < 0:
            continue
        if best is None or compare_versions(v, best) > 0:
            best = v
    return best

from __future__ import annotations

from typing import Any


def describe_upload(content_type: str, data: bytes) -> dict[str, Any]:
    """
    Describe an uploaded payload based on Content-Type header and leading bytes.

    Returns a dict:
      {
        "mime": <lower-cased media type without parameters>,
        "charset": <lower-cased charset parameter or None>,
        "image": <"png" | "jpeg" | "gif" | None>
      }

    Notes:
    - Parameter values may be quoted.
    - Content-Type may be empty; in that case "mime" is "" and charset is None.
    - Image detection is from signature bytes (leading magic numbers).
    """
    if content_type is None:
        content_type = ""

    # Local, dependency-free parsing to honor quoted ';' splits.
    def _split_header_params(header: str) -> list[str]:
        parts: list[str] = []
        buf: list[str] = []
        in_quotes = False

        for ch in header:
            if ch == '"':
                in_quotes = not in_quotes
                buf.append(ch)
                continue
            if ch == ";" and not in_quotes:
                parts.append("".join(buf).strip())
                buf.clear()
                continue
            buf.append(ch)

        tail = "".join(buf).strip()
        if tail:
            parts.append(tail)
        return parts

    def _parse_content_type(header: str) -> tuple[str, dict[str, str]]:
        if not header:
            return "", {}

        parts = _split_header_params(header)
        if not parts:
            return "", {}

        value = parts[0].strip().lower()
        params: dict[str, str] = {}

        for param in parts[1:]:
            if not param or "=" not in param:
                continue
            k, v = param.split("=", 1)
            k = k.strip().lower()
            v = v.strip()

            if len(v) >= 2 and v[0] == '"' and v[-1] == '"':
                v = v[1:-1]

            if k == "charset":
                v = v.lower()
            params[k] = v

        return value, params

    def _image_type_png_jpeg_gif(d: bytes) -> str | None:
        if not d:
            return None

        # PNG: 89 50 4E 47 0D 0A 1A 0A
        if d.startswith(b"\x89PNG\r\n\x1a\n"):
            return "png"

        # JPEG: FF D8 FF (third byte varies)
        if len(d) >= 3 and d.startswith(b"\xFF\xD8\xFF"):
            return "jpeg"

        # GIF: "GIF87a" or "GIF89a"
        if d.startswith(b"GIF87a") or d.startswith(b"GIF89a"):
            return "gif"

        return None

    mime, params = _parse_content_type(content_type)
    charset = params.get("charset")
    image = _image_type_png_jpeg_gif(data)

    return {"mime": mime, "charset": charset, "image": image}

