import asyncio
from typing import Any, List


def run_with_deadline(coros: list, seconds: float) -> list:
    """
    Run the given coroutines concurrently from ordinary synchronous code.

    - Runs all coroutines concurrently.
    - Waits up to `seconds` from the start.
    - Returns results in input order.
    - If a coroutine hasn't finished within the deadline, its slot is None and it is cancelled.
    - Exceptions from coroutines that *do* finish before the deadline propagate.
    - Safe to call repeatedly in the same process (creates and closes its own event loop).
    """
    if seconds is None:
        raise TypeError("seconds must be a number, not None")
    try:
        seconds_f = float(seconds)
    except (TypeError, ValueError) as e:
        raise TypeError("seconds must be a float") from e
    if seconds_f < 0:
        seconds_f = 0.0

    if not coros:
        return []

    # No running loop is assumed by the request, but be defensive.
    try:
        running_loop = asyncio.get_running_loop()
    except RuntimeError:
        running_loop = None
    if running_loop is not None:
        raise RuntimeError(
            "run_with_deadline must be called when no event loop is running."
        )

    loop = asyncio.new_event_loop()
    try:
        asyncio.set_event_loop(loop)

        async def _main() -> list:
            tasks = [loop.create_task(c) for c in coros]
            results: List[Any] = [None] * len(tasks)

            done, pending = await asyncio.wait(
                tasks, timeout=seconds_f, return_when=asyncio.ALL_COMPLETED
            )

            # Fill in results for completed tasks (propagate exceptions).
            for idx, t in enumerate(tasks):
                if t in done:
                    results[idx] = t.result()

            # Cancel timed-out tasks.
            for t in pending:
                t.cancel()

            if pending:
                # Ensure cancellations are processed; ignore CancelledError.
                await asyncio.gather(*pending, return_exceptions=True)

            return results

        return loop.run_until_complete(_main())
    finally:
        try:
            asyncio.set_event_loop(None)
        finally:
            loop.close()
